import Foundation

/// 农历年
public class LunarYear: YearUnit {
    private static let lock: NSLock = NSLock()
    static var LEAP: [[Int]] = {
        lock.lock()
        defer {
            lock.unlock() 
        }
        var leap: [[Int]] = []
        let chars: String = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_@"
        let months: [String] = [
            "080b0r0j0j0j0C0j0j0C0j0j0j0C0j0C0j0C0F0j0V0V0V0u0j0j0C0j0j0j0j0V0C0j1v0u0C0V1v0C0b080u110u0C0j0C1v9K1v2z0j1vmZbl1veN3s1v0V0C2S1v0V0C2S2o0C0j1Z1c2S1v0j1c0j2z1v0j1c0j392H0b2_2S0C0V0j1c0j2z0C0C0j0j1c0j0N250j0C0j0b081n080b0C0C0C1c0j0N",
            "0r1v1c1v0V0V0F0V0j0C0j0C0j0V0j0u1O0j0C0V0j0j0j0V0b080u0r0u080b0j0j0C0V0C0V0j0b080V0u080b0j0j0u0j1v0u080b1c0j080b0j0V0j0j0V0C0N1v0j1c0j0j1v2g1v420j1c0j2z1v0j1v5Q9z1v4l0j1vfn1v420j9z4l1v1v2S1c0j1v2S3s1v0V0C2S1v1v2S1c0j1v2S2_0b0j2_2z0j1c0j",
            "",
            "_",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "0B0j0V0j0j0C0j0j0j0C0j0C0j0j0C0j0m0j0j0j0j0C0j0C0j0j0u0j1c0j0j0C0C0j0j0j0j0j0j0j0j0u110N0j0j0V0C0V0j0b081n080b0CrU1O5e2SbX2_1Z0V2o141v0j0C0C0j2z1v0j1c0j7N1O420j1c0j1v2S1c0j1v2S2_0b0j0V0j0j1v0N1v0j0j1c0j1v140j0V0j0j0C0C0b080u1v0C0V0u110u0j0j0j0C0j0j0j0C0C0N0C0V0j0j0C0j0j0b080u110u0C0j0C0u0r0C0u080b0j0j0C0j0j0j"
        ]
        for m: String in months {
            var n: Int = 0
            let size: Int = m.count / 2
            var l: [Int] = []
            for y: Int in (0..<size) {
                let z: Int = y * 2
                var t: Int = 0
                var c: Int = 1
                for x: Int in stride(from: 1, through: 0, by: -1) {
                    let index: String.Index = chars.firstIndex(of: m[m.index(m.startIndex, offsetBy: z + x)])!
                    t += c * chars.distance(from: chars.startIndex, to: index)
                    c *= 64
                }
                n += t
                l.append(n)
            }
            leap.append(l)
        }
        return leap
    }()

    required override init(_ year: Int) throws {
        try Self.validate(year)
        try super.init(year)
    }
    
    public class func validate(_ year: Int) throws {
        try validateRange(year, -1, 9999, "lunar year")
    }

    public class func fromYear(_ year: Int) throws -> Self {
        try Self(year)
    }

    /// 天数
    public var dayCount: Int {
        var n: Int = 0
        for m: LunarMonth in months {
            n += m.dayCount
        }
        return n
    }

    /// 月数
    public var monthCount: Int {
        leapMonth < 1 ? 12 : 13
    }

    /// 闰月数字，1代表闰1月，0代表无闰月
    public var leapMonth: Int {
        if year == -1 {
            return 11
        }
        for i: Int in 0..<Self.LEAP.count {
            if Self.LEAP[i].contains(year) {
                return i + 1
            }
        }
        return 0
    }

    /// 干支
    public var sixtyCycle: SixtyCycle {
        SixtyCycle.fromIndex(year - 4)
    }

    /// 运
    public var twenty: Twenty {
        Twenty.fromIndex(Int(floor((Double(year) - 1864.0) / 20.0)))
    }

    /// 九星
    public var nineStar: NineStar {
        NineStar.fromIndex(63 + twenty.sixty.index * 3 - sixtyCycle.index)
    }

    /// 太岁方位
    public var jupiterDirection: Direction {
        Direction.fromIndex([0, 7, 7, 2, 3, 3, 8, 1, 1, 6, 0, 0][sixtyCycle.earthBranch.index])
    }
    
    public override func getName() -> String {
        "农历\(sixtyCycle)年"
    }
    
    public override func next(_ n: Int) throws -> Self {
        try Self.fromYear(year + n)
    }

    /// 首月（农历月，即一月，俗称正月）
    public var firstMonth: LunarMonth {
        try! LunarMonth.fromYm(year, 1)
    }

    /// 月份列表，一般有12个月，当年有闰月时，有13个月。
    public var months: [LunarMonth] {
        var l: [LunarMonth] = [LunarMonth]()
        let m: Int = leapMonth
        for i: Int in 1 ..< 13 {
            l.append(try! LunarMonth.fromYm(year, i))
            if i == m {
                l.append(try! LunarMonth.fromYm(year, -i))
            }
        }
        return l
    }
    
    /// 灶马头
    public var kitchenGodSteed: KitchenGodSteed {
        try! KitchenGodSteed.fromLunarYear(year)
    }
}
